    "text": "{\"duration\":98,\"version\":\"v2.0.0\",\"result\":{\"pages\":[{\"height\":394,\"lines\":[{\"direction\":1,\"text\":\"2制冷系统故障特征与数据来源\",\"position\":[60,2,438,2,438,34,60,34],\"score\":0.999,\"handwritten\":0,\"angle\":0,\"type\":\"text\"},{\"direction\":1,\"text\":\"2.1冰箱制冷系统故障特征\",\"position\":[62,34,307,34,307,58,62,58],\"score\":0.999,\"handwritten\":0,\"angle\":0,\"type\":\"text\"},{\"direction\":1,\"text\":\"冰箱制冷系统基于蒸气压缩循环工作。压缩机将低温低压制冷剂蒸气压缩为高温高压\",\"position\":[62,58,791,58,791,83,62,83],\"score\":0.998,\"handwritten\":0,\"angle\":0,\"type\":\"text\"},{\"direction\":1,\"text\":\"气体，制冷剂随后在冷凝器中放热冷凝，经节流装置降压后进入蒸发器吸收箱内热量，\",\"position\":[63,83,787,83,787,107,63,107],\"score\":0.999,\"handwritten\":0,\"angle\":0,\"type\":\"text\"},{\"direction\":1,\"text\":\"最终回到压缩机完成循环。在该循环中，压缩机反映系统驱动能力，冷凝器反映散热状\",\"position\":[63,108,800,108,800,132,63,132],\"score\":0.999,\"handwritten\":0,\"angle\":0,\"type\":\"text\"},{\"direction\":1,\"text\":\"态，蒸发器反映箱内吸热能力，节流装置影响制冷剂流量和蒸发压力。\",\"position\":[62,132,678,132,678,158,62,158],\"score\":0.998,\"handwritten\":0,\"angle\":0,\"type\":\"text\"},{\"direction\":1,\"text\":\"典型故障包括冷凝器污染、蒸发器风机衰退或失效、制冷剂不足或过量、传感器漂移、\",\"position\":[62,158,798,158,798,183,62,183],\"score\":0.999,\"handwritten\":0,\"angle\":0,\"type\":\"text\"},{\"direction\":1,\"text\":\"压缩机效率下降以及复合故障等。冷凝器污染会削弱散热能力，使冷凝温度和排气压力升高；\",\"position\":[23,183,815,183,815,207,23,207],\"score\":0.999,\"handwritten\":0,\"angle\":0,\"type\":\"text\"},{\"direction\":1,\"text\":\"蒸发器风机失效会削弱箱内换热，使蒸发侧温度和箱内温度控制效果发生变化；制冷剂不足\",\"position\":[24,208,808,208,808,232,24,232],\"score\":0.999,\"handwritten\":0,\"angle\":0,\"type\":\"text\"},{\"direction\":1,\"text\":\"可能导致蒸发压力、制冷量和过热度异常；传感器漂移会改变测量值与真实温度之间的关系；\",\"position\":[23,232,815,232,815,258,23,258],\"score\":0.999,\"handwritten\":0,\"angle\":0,\"type\":\"text\"},{\"direction\":1,\"text\":\"压缩机效率下降则可能引起功率、频率和制冷量响应异常。\",\"position\":[23,258,542,258,542,282,23,282],\"score\":0.998,\"handwritten\":0,\"angle\":0,\"type\":\"text\"},{\"direction\":1,\"text\":\"这些故障往往不是由单一变量突变决定，而是表现为多个运行参数统计特征的同步变化。\",\"position\":[62,283,815,283,815,307,62,307],\"score\":0.998,\"handwritten\":0,\"angle\":0,\"type\":\"text\"},{\"direction\":1,\"text\":\"例如，不可凝气体混入和冷凝器严重污染都可能引起冷凝侧压力和温度异常；制冷剂不足与\",\"position\":[24,308,807,308,807,332,24,332],\"score\":0.999,\"handwritten\":0,\"angle\":0,\"type\":\"text\"},{\"direction\":1,\"text\":\"复合污染故障也可能在蒸发压力、制冷量和COP上表现相近。因此，本文采用多源运行参数\",\"position\":[24,334,808,334,808,358,24,358],\"score\":0.998,\"handwritten\":0,\"angle\":0,\"type\":\"text\"},{\"direction\":1,\"text\":\"共同表征状态，并通过模型比较检验这些参数是否能够稳定区分不同故障类型。\",\"position\":[24,358,714,356,714,382,24,383],\"score\":0.998,\"handwritten\":0,\"angle\":0,\"type\":\"text\"}],\"angle\":0,\"width\":934}]},\"code\":200,\"message\":\"success\"}"
  }
]

